<template>
  <main class="nw-workspace"><header><router-link to="/fundthred"><NoteworthyBrand /></router-link><router-link to="/fundthred/noteworthy/app">Practice portal →</router-link></header><div class="nw-workspace-body"><p class="eyebrow">FundThred team</p><h1>NoteWorthy inquiries & activation</h1><p>Help practices finish their agreements, activate their trial, and confirm an ongoing plan.</p><p v-if="error" class="nw-alert nw-alert-error" role="alert">{{ error }}</p><p v-if="notice" class="nw-alert" role="status">{{ notice }}</p><button :disabled="busy" @click="load">Refresh queue</button>
    <section class="nw-panel"><h2>Practice inquiries</h2><p v-if="!inquiries.length">No inquiries yet.</p><div class="nw-table-scroll"><table v-if="inquiries.length" class="nw-table"><thead><tr><th>Practice</th><th>Contact</th><th>Topic</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="item in inquiries" :key="item.id"><td>{{ item.contact.practiceName }}</td><td>{{ item.contact.name }}<br/>{{ item.contact.email }}</td><td>{{ item.subject }}</td><td>{{ item.status }}</td><td><a :href="`https://plottwisthq.com/tickets?ticketId=${item.ticketId}`" target="_blank" rel="noopener noreferrer">Open ticket #{{ item.ticketId }} →</a></td></tr></tbody></table></div></section>
    <section class="nw-panel"><h2>Practice setup & trials</h2><p v-if="!practices.length">No registered practices yet.</p><div class="nw-table-scroll"><table v-if="practices.length" class="nw-table"><thead><tr><th>Practice</th><th>Owner</th><th>State</th><th>Trial ends</th><th>Deletion / retention</th><th></th></tr></thead><tbody><tr v-for="item in practices" :key="item.agencyId"><td>{{ item.name }}</td><td>{{ item.ownerEmail }}</td><td>{{ item.state }}</td><td>{{ date(item.trialEndsAt) }}</td><td>{{ item.deletionStatus || (item.scheduledDeletionAt?date(item.scheduledDeletionAt):'—') }}<small v-if="item.deletionError"> · {{ item.deletionError }}</small></td><td><button :disabled="busy||item.deletedAt" @click="selectPractice(item)">Review setup</button></td></tr></tbody></table></div></section>
    <section v-if="selected" class="nw-panel"><h2>{{ selected.name }} · activation review</h2><p v-if="!selected.policyAccepted" class="nw-alert">The owner must confirm the trial and data choices before activation.</p><button @click="showAgreements=!showAgreements">{{ showAgreements?'Hide agreements':'Open practice agreements' }}</button><OrganizationAgreementsView v-if="showAgreements" :key="selected.agencyId" embedded :initial-agency-id="selected.agencyId" />
      <form @submit.prevent="activate"><h3>Approve data access & start the 30-day trial</h3><div class="nw-form-pair"><label>Practice legal name<input v-model="review.legalName" required maxlength="1000" /></label><label>Practice legal address<input v-model="review.legalAddress" required maxlength="1000" /></label><label>Executed BAA archive ID<input v-model="review.baaId" required maxlength="36" /></label><label>Executed payroll service agreement reference<input v-model="review.serviceAgreementReference" required maxlength="1000" /></label><label>Agreed order reference<input v-model="review.orderReference" required maxlength="1000" /></label><label>Infrastructure & vendor readiness evidence<input v-model="review.infrastructureEvidence" required maxlength="4000" /></label></div><label class="nw-operator-check"><input v-model="review.verified" type="checkbox" required /> I reviewed these exact executed agreements, legal identity, and infrastructure evidence.</label><button :disabled="busy||!selected.policyAccepted">{{ busy?'Saving review…':'Approve data access' }}</button><p class="nw-small">Approval records your account. A repeated approval does not restart an existing trial.</p></form>
      <form v-if="activation?.activatedAt" @submit.prevent="continuePractice"><h3>Confirm an ongoing plan</h3><p>Use this after the commercial terms and billing arrangements are agreed. This records the plan confirmation; it does not charge a payment method.</p><label>Billing or agreed order reference<input v-model="billingReference" required maxlength="1000" /></label><label class="nw-operator-check"><input v-model="commercialConfirmed" type="checkbox" required /> I confirm the practice’s ongoing plan and billing arrangement.</label><button :disabled="busy">Activate ongoing plan</button></form>
    </section>
  </div></main>
</template>
<script setup>
import {defineAsyncComponent,onMounted,reactive,ref} from 'vue';
import api from '../services/api';
import NoteworthyBrand from '../components/noteworthy/NoteworthyBrand.vue';
import '../styles/noteworthyPayroll.css';import '../styles/noteworthyWorkspace.css';
const OrganizationAgreementsView=defineAsyncComponent(()=>import('./admin/OrganizationAgreementsView.vue'));
const practices=ref([]),inquiries=ref([]),selected=ref(null),activation=ref(null),busy=ref(false),error=ref(''),notice=ref(''),showAgreements=ref(false),billingReference=ref(''),commercialConfirmed=ref(false);
const review=reactive({legalName:'',legalAddress:'',baaId:'',serviceAgreementReference:'',orderReference:'',infrastructureEvidence:'',verified:false});
const config={headers:{'X-Noteworthy-Request':'1'},skipGlobalLoading:true};
const date=value=>value?String(value).slice(0,10):'—';
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();}catch(e){error.value=e.response?.data?.error?.message || 'The team queue could not be loaded. Operator access is required.';}finally{busy.value=false;}}
async function refresh(){const [p,i]=await Promise.all([api.get('/noteworthy/operator/practices',{skipGlobalLoading:true}),api.get('/noteworthy/operator/inquiries',{skipGlobalLoading:true})]);practices.value=p.data.practices || [];inquiries.value=i.data.inquiries || [];}
function load(){return run(refresh);}
function selectPractice(item){return run(async()=>{const {data}=await api.get(`/noteworthy/operator/practices/${item.agencyId}/activation`,{skipGlobalLoading:true});selected.value=item;activation.value=data;showAgreements.value=false;review.legalName=data.legalIdentity?.legalName || '';review.legalAddress=data.legalIdentity?.legalAddress || '';review.verified=false;});}
function activate(){return run(async()=>{activation.value=(await api.post(`/noteworthy/operator/practices/${selected.value.agencyId}/activate`,{...review},config)).data;await refresh();selected.value=practices.value.find(p=>p.agencyId===selected.value.agencyId);notice.value='Activation review saved. The 30-day trial begins on the first approval.';});}
function continuePractice(){return run(async()=>{await api.post(`/noteworthy/operator/practices/${selected.value.agencyId}/continue`,{billingReference:billingReference.value,confirmed:commercialConfirmed.value},config);await refresh();notice.value='Ongoing plan confirmed. Automatic trial deletion is no longer scheduled.';});}
onMounted(load);
</script>
<style scoped>
.nw-operator-check{display:flex!important;flex-direction:row!important;align-items:start;line-height:1.7}.nw-operator-check input{margin-top:5px}.nw-panel form{margin-top:25px;padding-top:20px;border-top:1px solid #dce7ee}
</style>
